testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted

class ItemData extends Resource:
	var price: int = 10

func run():
	var item_a := ItemData.new()
	var item_b := item_a
	item_b.price = 25
	return item_a.price
",
   "domanda": "Quanto vale `item_a.price` alla fine?",
   "spiegazione": "Le risorse in GDScript sono oggetti passati per riferimento. `item_b` non è una copia, ma punta allo stesso esatto oggetto di `item_a`. Modificare `item_b.price` cambia anche il valore di `item_a`."
  },
  {
   "codice": "extends RefCounted

class ItemData extends Resource:
	var price: int = 10

func run():
	var item_a := ItemData.new()
	var item_b := item_a.duplicate() as ItemData
	item_b.price = 25
	return item_a.price
",
   "domanda": "Quanto vale `item_a.price` alla fine?",
   "spiegazione": "Usando `duplicate()`, viene creata una copia indipendente della risorsa in memoria. Modificare `item_b` non ha alcun effetto su `item_a`, che mantiene il suo valore originale di 10."
  },
  {
   "codice": "extends RefCounted

class QuestData extends Resource:
	var reward: int = 100

func run():
	var quest := QuestData.new()
	quest.reward += 50
	return quest.reward
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "La risorsa viene istanziata con il valore predefinito di `reward` pari a 100. Nel codice aggiungiamo 50, quindi la funzione restituisce 150."
  },
  {
   "codice": "extends RefCounted

class Stats extends Resource:
	var health: int = 50

func run():
	var a := Stats.new()
	var b := Stats.new()
	b.health = 100
	return a.health == b.health
",
   "domanda": "Cosa restituisce `run()` (true o false)?",
   "spiegazione": "`a` e `b` sono due istanze distinte create con `.new()`. Hanno proprietà indipendenti (`50` e `100`), quindi il confronto tra i loro valori di salute restituisce `false`."
  }
 ]
}
